    if fixity['method'] not in ['md5', 'sha256']:
        raise ValueError("Fixity method should be either 'md5' or 'sha256'.")

    if fixity['tags'] != '':
        tags = fixity['tags'].split(',')
        for tag in tags:
            if tag not in manifest_files:
                raise ValueError("Manifest contains unknown file: {}".format(tag))

    if fixity['algorithm'] not in ['fips_180_2', 'iso_15978.5', 'iso_15978.3']:
        raise ValueError("Fixity algorithm should be either 'fips_180_2', 'iso_15978.5', or 'iso_15978.3'.")

