    return "".join(result)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    base = len(alphabet)
    inverse_alphabet = {letter: i for i, letter in enumerate(alphabet)}
    n = 0
    exp = 0
    for i in reversed(string):
        n += inverse_alphabet[i] * (base ** exp)
        exp += 1
    return n

