    """Return True if *seq* is a sequence of bytes/bytearrays/strings."""
    return (isinstance(seq, (list, tuple)) and
            all(isinstance(x, (bytes, bytearray, str)) for x in seq))

def _encode_sequence(seq):
    """Encode a sequence of bytes/bytearrays/strings."""
    return b"".join(seq)

def scale(self, other=None, recompute=False):
    if other is None:
        # Return the scale of this histogram
        if self._scale is None or recompute:
            self._scale = self.sum()
        return self._scale
    else:
        # Set the scale of this histogram
        if not isinstance(other, Real):
            raise LenaTypeError(f"Can't set scale to {other}")
        if self._scale is not None:
            # Compute the ratio of current to new scale
            ratio = other / self._scale
            # Update all bins in the histogram
            for bin in self.bins():
                self[bin] = int(round(self[bin] * ratio))
            self._scale = other
        else:
            raise LenaValueError("Can't change the scale of a histogram with zero area")

def scale(self, other=None):
    if other is None:
        return self.scale
    elif isinstance(other, (int, float)):
        self._scale_coordinates(other)
        return self
    else:
        raise ValueError("The `other` argument must be a numeric value.")

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative:
        if not iface.providedBy(candidate):
            raise Invalid(f"{candidate} does not claim to provide {iface}")
    info = inspect.getfullargspec(candidate)
    missing = []
    for method in iface:
        try:
            _method = getattr(candidate, method.name)
        except AttributeError:
            missing.append(f"the required method {method.name} was not found")
            continue
        for param in method.positional:
            if param.name not in info.args:
                missing.append(f"the method {method.name} does not have a required positional argument {param.name}")
        for param in method.var_positional:
            if info.varargs is None:
                missing.append(f"the method {method.name} does not have a required varargs argument {param.name}")
        for param in method.varkw:
            if info.varkw is None:
                missing.append(f"the method {method.name} does not have a required keyword argument {param.name}")
    for attr in iface:
        if not hasattr(candidate, attr.name):
            missing.append(f"the required attribute {attr.name} was not found")
    if missing:
        raise Invalid(f"{candidate} does not provide {iface}: {', '.join(missing)}")
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, ABCMeta):
        raise TypeError("iface must be an abc.ABCMeta instance")

    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")

    unimplemented_methods = []
    for meth in iface.getNotImplementedMethods():
        if not tentative and not meth.is_method_of(candidate):
            raise TypeError("candidate does not implement %s" % meth)
        if tentative and meth.is_method_of(candidate):
            unimplemented_methods.append(meth)

    if unimplemented_methods:
        raise TypeError("candidate does not implement %s" % unimplemented_methods)

    return candidate

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if bases and explicit_mc is not None:
        raise ValueError("Cannot specify both bases and explicit __metaclass__")

    if explicit_mc is not None:
        if not isinstance(explicit_mc, (type, NoneType)):
            raise ValueError("__metaclass__ must be a type or None")
        return explicit_mc

    if len(bases) == 0:
        return types.ObjectClass

    metaclass_order = [x for x in bases if isinstance(x, Metaclass)]
    if len(metaclass_order) > 1:
        raise ValueError("multiple metaclasses found for bases")
    elif len(metaclass_order) == 0:
        return classes.BaseClass
    else:
        return metaclass_order[0]

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is __marker:
            raise KeyError(key)
        else:
            return default
    value = self.get(key)
    self._redis.delete(key)
    return value

def popitem(self):
        """Remove and return the `(key, value)` pair most recently used."""
        key = max(self.keys(), key=self.get_last_used)
        value = self[key]
        del self[key]
        return (key, value)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

