def parse_diaspora_webfinger(document: str) -> Dict:
    json_url = None
    xrd_url = None
    try:
        j = json.loads(document)
        json_url = j["href"]
    except json.JSONDecodeError:
        xml = fromstring(document)
        json_url = xml.find(".//{http://ajax.googleapis.com/ajax/services/feed/load}.diaspora_json_url").text
    except ValueError:
        logger.error("Unable to parse Diaspora webfinger document: %s", document)
    except KeyError:
        logger.error("Unable to extract JSON URL from Diaspora webfinger document: %s", document)
    return {"json_url": json_url}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.

    :arg handle: Str
    :returns: Optional[str]
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        return None
    try:
        document, _, _ = fetch_document(host, "/.well-known/webfinger?resource=acct:%s" % quote(handle))
        return document
    except Exception as e:
        print(f"Failed to retrieve webfinger document: {e}")
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

