def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    if spec_content is None:
        raise IRValidatorException("Parameter 'spec_content' cannot be None")

    try:
        data = YAML().load(spec_content)
    except YAMLError as e:
        raise IRValidatorException("Error parsing YAML content: " + str(e))

    # validate required fields
    if not data["fields"]:
        raise IRValidatorException("Missing required field: 'fields'")
    if not data["fields"]["report_fields"]:
        raise IRValidatorException("Missing required field: 'report_fields'")
    if not data["fields"]["sampler"]:
        raise IRValidatorException("Missing required field: 'sampler'")
    if not data["fields"]["filename"]:
        raise IRValidatorException("Missing required field: 'filename'")

    return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if not yaml_file:
        raise ValueError("yaml_file argument must be supplied")

    try:
        with yaml_file.open() as f:
            data = yaml.load(f)

    except Exception as e:
        raise IRValidatorException(f"Failed to load data from {yaml_file}") from e

    try:
        validate_schema(data, cls.get_schema())

    except ValidationError as e:
        raise IRValidatorException(f"Mandatory data missing in schema: {e.message}")

    return data

