def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """

    # validate required arguments
    for arg in self._argspec.args:
        if arg in args and args[arg] is not None:
            continue
        if arg in self._argspec.defaults:
            continue
        return False

    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditions_met = []
    for option in options_spec:
        if option['required_when']:
            condition = option['required_when']
            for arg_name in condition.split('|'):
                if arg_name in args and args[arg_name] not in (None, False):
                    conditions_met.append(arg_name)
    return conditions_met

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if not isinstance(arg, str):
            continue
        if len(arg) > self.length:
            raise ValueError(f"The length of argument '{arg}' can't be longer than {self.length}")

def validate_choices_args(args):
    """
    Check if value of choice arguments is one of the available choices.
    :param args: The received arguments.
    """
    for arg in args:
        if isinstance(arg, str):
            # check if the argument is one of the available choices
            if arg not in self.choices:
                raise RuntimeError("Invalid choice: {}".format(arg))

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if len(args) != 2:
        raise TypeError("Expected exactly 2 arguments, got %s" % len(args))
    if type(args[0]) != int:
        raise TypeError("First argument must be an integer")
    if type(args[1]) != int:
        raise TypeError("Second argument must be an integer")
    if args[0] > args[1]:
        raise ValueError("First argument must not be greater than second argument")
    return args

def get_nested_custom_and_control_args(self, args):
